// The day in n8n's own time zone, as 2026-09-30.
const today = new Date().toLocaleDateString('en-CA');
// The five channels of the niche test. id matches the channel presets in RankReel; format is the one each channel uses.
const CHANNELS = [
  { id: 'rank-the-play', name: 'Rank The Play', niche: 'sports: football, basketball, cricket and more', format: 'countdown', news: 'sports' },
  { id: 'wait-really', name: 'Wait, Really?', niche: 'surprising did-you-know facts about everyday things, history and science', format: 'story', news: 'science discovery' },
  { id: 'tech-tier', name: 'Tech Tier', niche: 'tech, gadgets, phones, apps and AI', format: 'tiers', news: 'tech gadgets AI' },
  { id: 'money-levels', name: 'Money Levels', niche: 'money: luxury, prices, rich people and what things cost', format: 'levels', news: 'luxury billionaire price' },
  { id: 'guess-the-scene', name: 'Guess The Scene', niche: 'TV shows and films', format: 'quiz', news: 'movie TV series' },
];
const data = $getWorkflowStaticData('global');
// "Run now" comes through a webhook, whose item has headers; the hourly check does not.
const forced = Boolean($json.headers);
if (!forced && data.ideas?.date === today) return [];
return CHANNELS.map((channel) => ({ json: channel }));

const PLANNER = `You plan short vertical videos (YouTube Shorts) that are edited together from existing clips, for several channels.

The formats:
- countdown: clips ranked and counted down to number 1. Title like "Ranking the craziest near misses". items = 5 specific, well known things, the best one first.
- levels: clips that climb from level 1 to level 100. Title like "Level 1 to 100 trick shots". items = 5 feats, from the easiest to the most extreme.
- tiers: every clip lands in a tier from S down to D. Title like "Tier list of skate tricks". items = 5 specific, well known things, the best one first.
- quiz: viewers guess what each clip shows before the answer appears. Title like "Guess the footballer". items = the 5 answers.
- story: one surprising fact told by a voiceover. Title like "Why airplane windows have a tiny hole". items = the 5 shots to show, in order.

Rules:
- title: 3 to 7 words, plain text, no emoji, no hashtags, no quotation marks. It names a narrow angle, not just the topic.
- keywords: the 1 or 2 words from the title that say what the video is about.
- items: things that exist on video and that a viewer would recognise by name, 1 to 4 words each, no numbering. Be specific.
- search: a short phrase to type into YouTube or TikTok search to find these clips.
- Headlines are background on what is new this week. Use one only if it points to something people are looking for right now.
- The three ideas for a channel are all different from each other.`;

const ENTITIES = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'" };
const decode = (text) => text.replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1').replace(/&(#\d+|\w+);/g, (all, code) => (code[0] === '#' ? String.fromCodePoint(Number(code.slice(1))) : ENTITIES[code] ?? all));

const channels = $('Ideas due?').all().map((item) => item.json);
const feeds = $input.all();
const parts = channels.map((channel, at) => {
  const xml = String(feeds[at]?.json?.data ?? '');
  const headlines = [...xml.matchAll(/<item>[\s\S]*?<title>([\s\S]*?)<\/title>/g)]
    .map(([, title]) => decode(title).replace(/\s+-\s+[^-]+$/, '').trim())
    .filter(Boolean)
    .slice(0, 5);
  const news = headlines.length ? '\nHeadlines from this week:\n' + headlines.map((line) => '- ' + line).join('\n') : '';
  return `Channel id: ${channel.id}\nChannel: ${channel.name}, about ${channel.niche}. Format: ${channel.format}.${news}`;
});

const idea = {
  type: 'object',
  properties: {
    format: { type: 'string' },
    title: { type: 'string' },
    keywords: { type: 'array', items: { type: 'string' }, minItems: 1, maxItems: 2 },
    items: { type: 'array', items: { type: 'string' }, minItems: 5, maxItems: 5 },
    search: { type: 'string' },
  },
  required: ['format', 'title', 'keywords', 'items', 'search'],
};
const schema = {
  type: 'object',
  properties: {
    channels: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          id: { type: 'string', enum: channels.map((channel) => channel.id) },
          ideas: { type: 'array', items: idea, minItems: 3, maxItems: 3 },
        },
        required: ['id', 'ideas'],
      },
    },
  },
  required: ['channels'],
};

const day = new Date().toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' });
return [{
  json: {
    request: {
      systemInstruction: { parts: [{ text: PLANNER }] },
      contents: [{ role: 'user', parts: [{ text: `Today is ${day}.\n\n${parts.join('\n\n')}\n\nGive 3 video ideas for each channel, in that channel's format.` }] }],
      generationConfig: { temperature: 0.9, responseMimeType: 'application/json', responseJsonSchema: schema, thinkingConfig: { thinkingLevel: 'minimal' } },
    },
  },
}];

// The day in n8n's own time zone, as 2026-09-30.
const today = new Date().toLocaleDateString('en-CA');
const candidate = $json.candidates?.[0];
const text = (candidate?.content?.parts ?? []).filter((part) => !part.thought).map((part) => part.text ?? '').join('');
let reply = null;
try {
  reply = JSON.parse(text);
} catch {
  // Gemini was busy or said no. Nothing is kept, so the next hourly check tries again.
}
if (!Array.isArray(reply?.channels) || !reply.channels.length) return [{ json: { saved: false, why: $json.error?.message ?? 'no usable answer' } }];
const data = $getWorkflowStaticData('global');
data.ideas = { date: today, channels: Object.fromEntries(reply.channels.map((channel) => [channel.id, channel.ideas])) };
return [{ json: { saved: true, channels: reply.channels.length } }];

// The day in n8n's own time zone, as 2026-09-30.
const today = new Date().toLocaleDateString('en-CA');
const data = $getWorkflowStaticData('global');
const forced = Boolean($json.headers);
if (!forced && data.history?.[today]) return [];
// The handles are the ones RankReel last sent, from its channel presets.
return (data.handles ?? []).map((handle) => ({ json: { handle } }));

const page = String($json.data ?? '');
const handle = $('Scores due?').item.json.handle;
const id = page.match(/<link rel="canonical" href="https:\/\/www\.youtube\.com\/channel\/(UC[\w-]{22})"/)?.[1] ?? '';
return { json: { handle, id } };

// The day in n8n's own time zone, as 2026-09-30.
const today = new Date().toLocaleDateString('en-CA');
const found = $('Find the channel id').all().map((item) => item.json);
const feeds = $input.all();
const snapshot = {};
found.forEach((channel, at) => {
  if (!channel.id) return;
  const xml = String(feeds[at]?.json?.data ?? '');
  const views = [...xml.matchAll(/<media:statistics views="(\d+)"/g)].map(([, count]) => Number(count));
  const total = views.reduce((sum, count) => sum + count, 0);
  snapshot[channel.handle] = { views: total, videos: views.length, perVideo: views.length ? Math.round(total / views.length) : 0 };
});
if (!Object.keys(snapshot).length) return [{ json: { saved: false } }];
const data = $getWorkflowStaticData('global');
data.history = { ...(data.history ?? {}), [today]: snapshot };
// Two months of days is plenty to see which niche grows.
data.history = Object.fromEntries(Object.entries(data.history).sort(([a], [b]) => a.localeCompare(b)).slice(-60));
return [{ json: { saved: true, channels: Object.keys(snapshot).length } }];

const data = $getWorkflowStaticData('global');
// RankReel sends its channels' handles, which the daily score snapshot then uses.
const handles = String($json.query?.handles ?? '').split(',').map((handle) => handle.trim()).filter((handle) => /^@[\w.-]{3,30}$/.test(handle));
if (handles.length) data.handles = [...new Set(handles)].slice(0, 10);
return [{ json: { ideas: data.ideas ?? null, history: data.history ?? {} } }];
